namespace StarlightSyndicateDemo;
public sealed partial class DemoGame
{
 void RunDogmaUiChecks45(int stage){var w=desktop.Last();switch(stage){case 0:UiCheck(w.InfoTab=="Mechanics","Mechanics tab selected");UiCheck(ResolveInformation(w.InfoKey)!.Tabs["Mechanics"].Count>20,"source hull attributes rendered");UiCheck(ui.Hits.Any(h=>h.Owner==w.Owner&&h.Tip=="Info tab / Mechanics"),"native mechanics tab control");var link=ui.Hits.First(h=>h.Owner==w.Owner&&h.Tip.StartsWith("Info link / dogma45/dogmaAttributes/"));TestClick(link.Rect.Center.ToVector2());UiCheck(w.InfoKey.StartsWith("dogma45/dogmaAttributes/"),"attribute link navigates to record");break;case 1:UiCheck(ResolveInformation(w.InfoKey)!.Tabs.ContainsKey("Source audit"),"original attribute fields inspectable");InformationHistory(w,-1);UiCheck(w.InfoKey.StartsWith("item/"),"window-local back navigation");NavigateInformation(w,"dogma45/dogmaEffects/10");w.InfoTab="Support";break;case 2:UiCheck(ResolveInformation(w.InfoKey)!.Tabs["Support"].Any(r=>r.Value=="Unsupported"),"unsupported attack mechanics visible");UiCheck(ui.Hits.Any(h=>h.Owner==w.Owner&&h.Tip=="Info tab / Support"),"support tab control rendered");InformationHistory(w,-1);w.InfoTab="Mechanics";Console.WriteLine("8 Pass45 dogma UI checks passed.");break;}}
